// shared/bandDraft.js — the strategy (band) draft's data switch, read by the server and the client alike.
// data/config.json bandDraft.duplicatesAllowed (generated by tools/build-data.mjs) decides whether two seats of the
// same co-op match may take the same strategy: true = 多人可选同一个策略 (the official illustration shows teammates'
// picks not greyed out — docs/research/01-core-data.json criticAddendum.bandDraft.duplicatesAllowed), false = the old
// 「队友已选」 rule (research 09 §5 read the guidebook page the other way). The owner's call of 2026-10-24: duplicates
// are allowed. Pure (no Node APIs), so server/match/gamedata.js (GameData.bandDraft → Match.bandTaken) and
// public/js/screens/bandDraft.js (the 队友已选 mark / the timeout's free-band hunt) read one definition.

/** The documented defaults of data/config.json bandDraft (DEFAULTS.bandDraft in server/match/gamedata.js). */
export const BAND_DRAFT_DEFAULTS = Object.freeze({
  skipsPerPlayer: 1,
  /** 多人可选同一个策略: true unless the data says otherwise (the official rule; research 01 criticAddendum). */
  duplicatesAllowed: true,
  timeoutBandId: 'band_bldsk',
});

/**
 * Whether two seats may take the same strategy, from a data/config.json (or a mode record) `bandDraft` object.
 * A missing / malformed value means the official rule: duplicates are allowed.
 * @param {{ bandDraft?: { duplicatesAllowed?: unknown } }|null|undefined} config data/config.json (or a mode override)
 * @returns {boolean}
 */
export function bandDuplicatesAllowed(config) {
  const v = config && typeof config === 'object' && config.bandDraft && typeof config.bandDraft === 'object'
    ? config.bandDraft.duplicatesAllowed : undefined;
  return typeof v === 'boolean' ? v : BAND_DRAFT_DEFAULTS.duplicatesAllowed;
}
